624	func (s *GmetaStore) commitEntries(refName plumbing.ReferenceName, parentHash, rootTreeHash plumbing.Hash, targetPath, basePath string, entries map[string]object.TreeEntry, message, authorName, authorEmail string) error {
625		// Convert entries to relative paths (strip basePath prefix)
626		relEntries := make(map[string]object.TreeEntry, len(entries))
627		for path, entry := range entries {
628			relPath := strings.TrimPrefix(path, basePath)
629			if relPath == path {
630				continue
631			}
632			relEntries[relPath] = entry
633		}
