652		newRootHash, err := UpdateSubtree(s.repo, rootTreeHash, parentSegments, []object.TreeEntry{
653			{Name: leafName, Mode: filemode.Dir, Hash: targetTreeHash},
654		}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
655		if err != nil {
